    public class ConsolidationReportService : ServiceBase, IConsolidationReportService
    {
        public IEnumerable<SelectListItem> GetCurrency(Age_Rpt_ConsolidatedGroupSelCurrency criteria)
        {
            Func<IDataReader, Currency> mappingFunc;
            mappingFunc = r =>
                {
                    var res = new Currency
                        {
                            CurrencyID = Convert.ToInt32(r["Currency"]),
                            CurrencyName = r["CurrencyName"].ToString1()
                        };

                    return res;
                };

            var result = _repository.Fetch<Currency>(criteria, mappingFunc).ToSelectListItem("CurrencyID",
                                                                                             "CurrencyName");
            return result;
        }

        public IEnumerable<ConsolidateReport> GetData(Age_Rpt_ConsolidatedGroup criteria)
        {
            Func<IDataReader, ConsolidateReport> mappingFunc;
            mappingFunc = r =>
                {
                    var res = new ConsolidateReport
                        {
                            LevelID = Convert.ToInt32(r["roleid"] == DBNull.Value ? 0 : r["roleid"]),
                            UserName = r["username"].ToString1(),
                            CurrencyID = Convert.ToInt32(r["currency"] == DBNull.Value ? 0 : r["currency"]),
                            Turnover = Convert.ToDouble(r["turnover"] == DBNull.Value ? 0 : r["turnover"]),
                            MemberWinloss = Convert.ToDouble(r["member_winlost"] == DBNull.Value ? 0 : r["member_winlost"]),
                            MemberComm = Convert.ToDouble(r["member_comm"] == DBNull.Value ? 0 : r["member_comm"]),
                            MemberTotal = Convert.ToDouble(r["member_total"] == DBNull.Value ? 0 : r["member_total"]),
                            OwnerTurnover = Convert.ToDouble(r["owner_turnover"] == DBNull.Value ? 0 : r["owner_turnover"]),
                            OwnerWinloss = Convert.ToDouble(r["owner_winlost"] == DBNull.Value ? 0 : r["owner_winlost"]),
                            OwnerComm = Convert.ToDouble(r["owner_comm"] == DBNull.Value ? 0 : r["owner_comm"]),
                            OwnerTotal = Convert.ToDouble(r["owner_total"] == DBNull.Value ? 0 : r["owner_total"]),
                            Company = Convert.ToDouble(r["company"] == DBNull.Value ? 0 : r["company"]),
                            BetCount = Convert.ToInt32(r["betcount"] == DBNull.Value ? 0 : r["betcount"])
                        };

                    res.Level = ReportService.GetLevelTitle(res.LevelID);

                    res.CurrencyName = res.CurrencyID.ToString(); // RemotingRef.RefData.GetExchangeData(res.CurrencyID).Currency;

                    if (criteria.ReportType == 1)
                    {
                        //UserName
                        try
                        {
                            res.CustID = Convert.ToInt32(r["breakdown"] == DBNull.Value ? 0 : r["breakdown"]);
                            res.CustName = string.Empty;
                        }
                        catch
                        {
                            res.CustID = 0;
                            res.CustName = string.Empty;
                        }
                    }
                    else if (criteria.ReportType == 2)
                    {
                        //Daily
                        try
                        {
                            res.Daily = Convert.ToDateTime(r["breakdown"].ToString1().ToAgentDate());
                        }
                        catch 
                        {
                            res.Daily = new DateTime();
                        }
                    }
                    else if (criteria.ReportType == 3)
                    {
                        //Sport
                        try
                        {
                            res.SportID = Convert.ToInt32(r["breakdown"]);
                            res.SportName = ReportService.GetSportName(res.SportID);
                            //res.SportName = Helper.SportTypes[res.SportID];
                        }
                        catch
                        {
                            res.SportID = 0;
                            res.SportName = string.Empty;
                        }
                    }

                    return res;
                };

            var result = _repository.Fetch<ConsolidateReport>(criteria, mappingFunc);
            if (criteria.ReportType == 3)
            {
                result = result.OrderBy(m => m.SportID).ToList();
            }

            return result;
        }

        public MemoryStream ExportExcel(Age_Rpt_ConsolidatedGroup criteria, List<ConsolidateReport> data)
        {
            if (data == null)
            {
                criteria.BalanceUpDate = ReportService.BalanceUp.BalanceUpDay;
                criteria.CustID = Convert.ToInt32(UserSession.Current.CustId);
                data = (List<ConsolidateReport>)this.GetData(criteria);
            }

            ConsolidateReportExcelService _reportService = new ConsolidateReportExcelService();

            return _reportService.Generate(criteria, data);
        }
    }
